package com.kisa.tmaprouteprobe;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.text.Spanned;import android.text.style.ForegroundColorSpan;import org.json.*;import java.lang.reflect.*;import java.io.*;import java.nio.file.*;
/** Real screen layout checks; only UI fixtures are injected, never navigation/GPS packets. */
